# ------------------------------------------------------------------
# Repair
# ------------------------------------------------------------------
def _run_repair(self) -> FrozenRepair:
    flow_count = len(self.flows)
    if flow_count == 0:
        return FrozenRepair((), (), ())

    trials = self.trials
    epsilon = self.epsilon
    seed = self.seed

    internal_pred, external_pred = self._predictions()
    routes_enabled = internal_pred is not None

    # Ordered baseline pools.  Reports come before the denoised/clamped
    # demand prediction, exactly as in the wire contract.
    pools: List[List[int]] = []
    for flow in self.flows:
        pool: List[int] = []
        if flow.source_key is not None:
            value = self.counter_values[flow.source_key]
            if value is not None:
                pool.append(value)
        if flow.destination_key is not None:
            value = self.counter_values[flow.destination_key]
            if value is not None:
                pool.append(value)
        if routes_enabled:
            if flow.kind == "internal":
                prediction = internal_pred.get(flow.pair, 0)  # type: ignore[union-attr]
            else:
                prediction = external_pred[flow.pair]
            if prediction > flow.capacity:
                prediction = flow.capacity
            pool.append(prediction)
        pools.append(pool)

    # Reproducible scenario samples at every router incidence.  The
    # target's own sample cancels from its remainder but is retained here
    # because it affects derived remainders for the other incident flows.
    samples: Dict[Tuple[int, int], List[int]] = {}
    for router in self.routers:
        for idx in self.incident_by_router[router]:
            flow = self.flows[idx]
            pool = pools[idx]
            if not pool:
                samples[(router, idx)] = [0] * trials
                continue
            plen = len(pool)
            a, b = flow.pair
            arr: List[int] = []
            prefix = f"{seed}:{router}:"
            suffix = f":{a}:{b}"
            for t in range(trials):
                digest = hashlib.sha256(
                    f"{prefix}{t}{suffix}".encode("ascii")
                ).digest()
                w = int.from_bytes(digest[:8], "big")
                arr.append(pool[w % plen])
            samples[(router, idx)] = arr

    # Raw (unclamped) remainders for every incidence, and the current
    # router-evidence band for each incidence.
    raw_remainders: Dict[Tuple[int, int], List[int]] = {}
    router_bands: Dict[Tuple[int, int], Tuple[int, int]] = {}
    for router in self.routers:
        incident = self.incident_by_router[router]
        if not incident:
            continue
        for idx in incident:
            raw_remainders[(router, idx)] = [0] * trials

        for t in range(trials):
            total_in = 0
            total_out = 0
            for idx in incident:
                flow = self.flows[idx]
                value = samples[(router, idx)][t]
                if flow.src == router:      # outgoing
                    total_out += value
                else:                        # incoming
                    total_in += value
            for idx in incident:
                flow = self.flows[idx]
                value = samples[(router, idx)][t]
                if flow.src == router:
                    # Replacement target's old sample is excluded from
                    # the outgoing total, then cancels.
                    remainder = total_in - (total_out - value)
                else:
                    remainder = total_out - (total_in - value)
                raw_remainders[(router, idx)][t] = remainder

        for idx in incident:
            router_bands[(router, idx)] = _agreement_with_clamp(
                raw_remainders[(router, idx)],
                self.flows[idx].capacity,
                epsilon,
            )

    def combine(idx: int) -> Tuple[int, int]:
        entries: List[Tuple[int, int]] = [
            (value, trials) for value in pools[idx]
        ]
        for router in self.flows[idx].endpoints:
            rep, mass = router_bands[(router, idx)]
            if mass:
                entries.append((rep, mass))
        return _agreement(entries, epsilon)

    candidates: List[Tuple[int, int]] = [combine(idx)
                                          for idx in range(flow_count)]
    max_possible_support = 5 * trials
    buckets: List[int] = [0] * (max_possible_support + 1)
    for idx, (_, support) in enumerate(candidates):
        buckets[support] |= (1 << idx)
    current_max = max(candidates[idx][1] for idx in range(flow_count))

    remaining = [True] * flow_count
    fixed_values = [0] * flow_count
    fixed_confidences: List[Tuple[int, int]] = [(0, trials)] * flow_count
    publication_order: List[Tuple[int, int]] = []

    for _ in range(flow_count):
        while current_max > 0 and buckets[current_max] == 0:
            current_max -= 1
        bits = buckets[current_max]
        if not bits:
            # Defensive fallback; valid evidence nonempty should avoid it.
            for candidate_idx in range(flow_count):
                if remaining[candidate_idx]:
                    bits = 1 << candidate_idx
                    current_max = candidates[candidate_idx][1]
                    break
        low_bit = bits & -bits
        idx = low_bit.bit_length() - 1
        value, support = candidates[idx]
        fixed_values[idx] = value
        fixed_confidences[idx] = (support, trials)
        publication_order.append(self.flows[idx].pair)
        remaining[idx] = False
        buckets[current_max] &= ~low_bit

        # Replace this flow's sampled value with its fixed value in the
        # evidence of every other still-unfixed flow at its endpoints.
        affected = set()
        for router in self.flows[idx].endpoints:
            flow_fixed = self.flows[idx]
            dir_fixed = 1 if flow_fixed.src == router else -1
